r=subprocess.run(cmd,capture_output=True,text=True,timeout=90);(root/'actual-graph-build.log').write_text(r.stdout+r.stderr);r.check_returncode()
checks=[]
with open('/home/ubuntu/.spacepdhcg-gpu.lock','a') as lock:
 fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
